STUDY = r"\b(studied|study|trained|train|schooled|educated|graduated|went to|recorded at|doctorate|degree|degrees|attended|came out of|alumni|graduates?)\b"
ONRE, STRE = re.compile(ON), re.compile(STUDY, re.I)
def split(p): return re.split(r'(?<=[.])\s+(?=[A-Z])', p)
def verdict(s):
    on, st = bool(ONRE.search(s)), bool(STRE.search(s))
    if st and not on: return 'cut'
    return 'keep'
